import ctypes as c, errno, json, os, subprocess
lib=c.CDLL('libseccomp.so.2',use_errno=True)
lib.seccomp_init.argtypes=[c.c_uint32]; lib.seccomp_init.restype=c.c_void_p
lib.seccomp_syscall_resolve_name.argtypes=[c.c_char_p]; lib.seccomp_syscall_resolve_name.restype=c.c_int
lib.seccomp_rule_add.argtypes=[c.c_void_p,c.c_uint32,c.c_int,c.c_uint]
lib.seccomp_load.argtypes=[c.c_void_p]; lib.seccomp_release.argtypes=[c.c_void_p]
ctx=lib.seccomp_init(0x7fff0000)
if not ctx: raise RuntimeError('Could not create local-only filter')
for name in (b'socket', b'connect', b'io_uring_setup'):
    nr=lib.seccomp_syscall_resolve_name(name)
    if nr<0 or lib.seccomp_rule_add(ctx,0x00050000 | errno.EPERM,nr,0)!=0: raise RuntimeError('Could not block '+name.decode())
if lib.seccomp_load(ctx)!=0: raise RuntimeError('Could not enable local-only filter')
lib.seccomp_release(ctx)
home=os.environ['HOME']
env={'HOME':home,'PATH':home+'/.bun/bin:/usr/local/bin:/usr/bin:/bin','LANG':'C.UTF-8'}
cli=home+'/.bun/bin/gbrain'
name='Kloufathab'
def run(*args):
    p=subprocess.run([cli,*args],env=env,stdin=subprocess.DEVNULL,capture_output=True,text=True,check=False,timeout=55)
    if p.returncode: raise RuntimeError(f'GBrain {args[0]} exited {p.returncode}: '+p.stderr[:1200])
    return json.loads(p.stdout)
run('remember',"The user's sister's new cat is called "+name+'.','--entity',name,'--visibility','private','--provenance','User explicitly asked to remember this in this conversation.','--content-origin','user_said','--json')
result=run('recall','--grep',name,'--json')
def found(v):
    if isinstance(v,dict):
        if v.get('visibility')=='private' and any(isinstance(x,str) and "sister's new cat is called "+name in x for x in v.values()): return True
        return any(found(x) for x in v.values())
    return isinstance(v,list) and any(found(x) for x in v)
if not found(result): raise RuntimeError('Recall did not confirm the private fact')
print('Private GBrain fact verified in a separate local recall process.')
